    "citations": [
      {
        "event_id": "lite_evt_00300",
        "explanation": "The doctor instructed a dizzy postoperative patient to take antihypertensive medication strictly by the discharge sheet and not use measured BP to decide, despite not knowing the exact medication/dose and despite hypotension/fall risk.",
